// Weapon fundamental runes (Player Core equipment rules): a potency rune grants an item bonus
// to attack rolls; a striking rune adds extra weapon damage dice (Striking +1, Greater +2,
// Major +3). Both default to none on a freshly added weapon.
export const POTENCY_RUNES = [
  { value: 'none', label: 'None', bonus: 0 },
  { value: '+1', label: '+1 Potency', bonus: 1 },
  { value: '+2', label: '+2 Potency', bonus: 2 },
  { value: '+3', label: '+3 Potency', bonus: 3 },
];
export const STRIKING_RUNES = [
  { value: 'none', label: 'None', extraDice: 0 },
  { value: 'striking', label: 'Striking', extraDice: 1 },
  { value: 'greater-striking', label: 'Greater Striking', extraDice: 2 },
  { value: 'major-striking', label: 'Major Striking', extraDice: 3 },
];

export const RANK_NAMES = ['Untrained', 'Trained', 'Expert', 'Master', 'Legendary'];
export const RANK_BONUS = [0, 2, 4, 6, 8];

export function calcMod(score) { return Math.floor((score - 10) / 2); }
export function calcProfBonus(rank, level) { return rank > 0 ? level + RANK_BONUS[rank] : 0; }
export function fmtMod(n) { return n >= 0 ? `+${n}` : `${n}`; }

// Ancestry HP is a flat one-time grant; class HP and the Constitution modifier are both
// gained again every level (Player Core p.29: "increase your maximum Hit Points by the
// amount indicated for your class" each level, recalculated whenever Con mod changes).
export function calcHpMax(ancestryHp, classHp, conMod, level, hasToughness) {
  const lvl = level || 1;
  return (ancestryHp || 0) + ((classHp || 0) + (conMod || 0)) * lvl + (hasToughness ? lvl : 0);
}

